 const tournamentSummary=`<section class="panel tournament-panel stats-glow glow-tournament" data-home-mode="tournament"><div class="section-head"><h2 class="tournament">Tournament Records</h2><a class="tournament" href="/tournament_stats">Stats ↗</a></div><div class="mini-stats joined-metrics"><div><b class="tournament">${completed.length}</b><small>Completed</small></div><div><b class="tournament">${entered??'—'}</b><small title="Entry slots in completed brackets; repeat appearances count each time">Tracks entered</small></div><div><b class="tournament">${songs.reduce((n,s)=>n+Number(s.podiums||0),0)}</b><small>Podiums</small></div></div>${homeBracketBar(completed)}</section>`;
 main.innerHTML=`<section class="hero"><h1>Song Ranker</h1></section><section class="mode-section" id="play"><div class="section-head"><h2>Ways to Play</h2></div><div class="modes"><a class="mode-card standard" href="/game"><span class="mode-icon">🔥</span><h2>Standard Vote</h2></a><a class="mode-card recognition" href="/trivia"><span class="mode-icon">🧠</span><h2>Trivia</h2></a><a class="mode-card tournament" href="/tournament"><span class="mode-icon">🏆</span><h2>Tournament</h2></a><a class="mode-card guesser" href="/elo_guesser"><span class="mode-icon">🎯</span><h2>Elo Guesser</h2></a><a class="mode-card shelves" href="/album_shelves"><span class="mode-icon">🗂️</span><h2>Album Shelves</h2></a></div></section><div class="stats home-collection-totals" role="group" aria-label="Collection totals">${stat('Songs',songs.length)}${stat('Artists',artists.length,'artist')}${stat('Albums',albums.filter(properAlbum).length,'album')}</div><div class="spotlights home-record-stats" role="group" aria-label="Mode records">${triviaSummary}${tournamentSummary}${window.SpecialModes.homeSummary()}</div>${shelf('songs','Top Tracks',songs,'/leaderboard')}${shelf('artists','Top Artists',artists,'/artists')}${shelf('albums','Top Albums',albums.filter(properAlbum),'/albums')}${homeRecords(recognized,champions)}${window.SpecialModes.homeBanners()}`;
 attachShelves();
