const shelfState=new Map();
const autoScrollers=new Set(),autoScrollStates=new WeakMap();
function attachAutoScroll(el,vertical=false){let state=autoScrollStates.get(el);if(!state){state={paused:false,timer:null,manualUntil:0};autoScrollStates.set(el,state);if(!vertical)shelfState.set(el.id,state);const pause=()=>state.paused=true,resume=()=>state.paused=false;el.addEventListener('mouseenter',pause);el.addEventListener('mouseleave',resume);el.addEventListener('focusin',pause);el.addEventListener('focusout',e=>{if(!el.contains(e.relatedTarget))resume()});el.addEventListener('touchstart',pause,{passive:true});el.addEventListener('touchend',resume,{passive:true});el.addEventListener('touchcancel',resume,{passive:true})}
 if(state.timer||matchMedia('(prefers-reduced-motion: reduce)').matches)return;state.timer=setInterval(()=>{if(state.paused||state.manualUntil>Date.now()||document.hidden||!el.isConnected)return;const max=vertical?el.scrollHeight-el.clientHeight:el.scrollWidth-el.clientWidth;if(max<=1)return;const key=vertical?'scrollTop':'scrollLeft';el[key]=el[key]>=max-1?0:Math.min(max,el[key]+.8)},35);autoScrollers.add(state)
}
function attachShelves(){$$('.scroller').forEach(el=>attachAutoScroll(el))}
window.addEventListener('pagehide',()=>{autoScrollers.forEach(state=>{clearInterval(state.timer);state.timer=null});autoScrollers.clear()});
window.addEventListener('pageshow',e=>{if(e.persisted&&page==='home'){attachShelves()}});

function matchRow(h){const w=byId(songs,h.winner_id),l=byId(songs,h.loser_id);if(!w||!l)return '';const side=(s,win)=>`<a class="match-song ${win?'match-winner':'match-loser'}" aria-label="${win?'Winner':'Loser'}: ${esc(s.title)}" href="${urlFor('songs',s)}">${artwork(s)}<div><strong class="${win?'song':'loss'}">${esc(s.title)}</strong><small>${esc(s.artist)}</small></div></a>`;return `<div class="match-row" data-match-mode="${h.mode}"><div class="match-mode"><span class="badge ${h.mode==='blind'?'blind':'standard'}">${h.mode==='blind'?'Blind':h.mode==='standard'?'Non-blind':'Unknown'}</span><small>${esc((h.created_at||'').slice(0,10))}</small></div>${side(w,true)}<span class="vs-small">VS</span>${side(l,false)}</div>`}
let historyFilter='all',songId;
