 const winner=i===gameWinner,overlay=revealed?`<div class="score-reveal elo-reveal ${winner?'score-win':'score-loss'}" role="status"><small>Elo</small><div class="score-values"><span class="score-before">${Math.round(gameOld[i])}</span><span class="score-arrow" aria-hidden="true">→</span><strong class="elo-score" id="elo-${i}">${Math.round(gameOld[i])}</strong></div><b class="elo-delta ${winner?'':'loss'}" id="delta-${i}">${winner?'↑ +':'↓ '}${Math.round(gameChanges[i])}</b></div>`:'';
 return `<article class="game-card ${revealed?(winner?'winner':'loser'):''}">${matchCover(s,'game-audio-'+i,blind&&!revealed,overlay)}<h2>${blind&&!revealed?'Track '+('AB'[i]):`<a class="song" title="${esc(s.title)}" href="${urlFor('songs',s)}">${esc(s.title)}</a>`}</h2><div class="game-meta">${blind&&!revealed?'':gameMetadata(s)}</div><button class="btn primary vote-btn" data-vote="${i}" ${revealed?'disabled':''}>${revealed?(winner?'✓ Winner':'Runner-up'):'Vote for '+('AB'[i])}</button></article>`;
