function tableRows(type){const q=normal(tableQuery);return records(type).filter(r=>normal(tableColumns[type].map(([k])=>tableValue(r,k)).join(' ')).includes(q)&&Object.entries(tableFilters).every(([k,v])=>normal(tableValue(r,k)).includes(normal(v)))).sort((a,b)=>{const av=tableValue(a,tableSort),bv=tableValue(b,tableSort);return (typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv),undefined,{numeric:true}))*tableDir})}
function renderManage(type){$('#dev-main').innerHTML=devTitle(type==='tags'?'Tags':type[0].toUpperCase()+type.slice(1))+`<form class="search-form" id="manage-search"><input id="manage-query" type="search" aria-label="Filter ${type}" placeholder="Search ${type}…" value="${esc(tableQuery)}"><button type="submit" aria-label="Search ${type}">↵</button></form>${columnChooser(type)}<div class="data-scroll"><table class="data-table"><thead><tr>${columns(type).map(([k,name])=>`<th><button type="button" data-sort="${k}" style="background:none;border:0;color:inherit;font:inherit;padding:0;text-transform:inherit">${name} ↕</button></th>`).join('')}<th>Actions</th></tr><tr class="filters">${columns(type).map(([k,name])=>`<th><input class="column-filter" data-column="${k}" value="${esc(tableFilters[k]||'')}" placeholder="${name==='Cover'?'URL':name}" aria-label="Filter ${name}"></th>`).join('')}<th></th></tr></thead><tbody id="manage-rows"></tbody></table></div><div class="dev-pagination"><span class="table-count" id="table-count" role="status"></span><div><button class="btn small" data-table-prev>Previous</button> <button class="btn small" data-table-next>Next</button></div></div>`;renderTableBody(type)}
function renderTableBody(type=devView){const all=tableRows(type),offset=tablePage*30,rows=all.slice(offset,offset+30);$('#manage-rows').innerHTML=rows.map(r=>`<tr>${columns(type).map(([k])=>`<td>${k==='cover_url'?artwork(r,type):k==='name'?`<strong>${clipped(r.name)}</strong>`:k==='preview'?(r.audio_url?'✓':'—'):['elo_score','score','avg_elo'].includes(k)?`<strong class="${k==='score'&&type!=='songs'?colour(type):'standard'}">${Math.round(Number(tableValue(r,k)))}</strong>`:clipped(tableValue(r,k)===''?'—':tableValue(r,k))}</td>`).join('')}<td><div class="table-actions"><button class="btn small" data-edit="${type}" data-id="${r.id}">Edit</button>${type==='songs'?`<button class="btn small" data-song-stats="${r.id}">Stats</button>`:''}<button class="btn small danger" data-delete="${type}" data-id="${r.id}">Delete</button></div></td></tr>`).join('')||`<tr><td colspan="${columns(type).length+1}" style="text-align:center;padding:30px">No records</td></tr>`;$('#table-count').textContent=all.length+' records · '+(all.length?offset+1:0)+'–'+Math.min(offset+30,all.length);$('[data-table-prev]').disabled=tablePage===0;$('[data-table-next]').disabled=offset+30>=all.length}
function renderImport(){$('#dev-main').innerHTML=devTitle('Apple Music')+`<form class="search-form" id="apple-search"><input id="apple-query" type="search" value="${esc(importQuery)}" placeholder="Apple Music link or search…" aria-label="Search Apple Music"><button type="submit" aria-label="Search Apple Music">↵</button></form><div class="checkboxes import-option"><label><input type="checkbox" id="keep-import" ${keepImport?'checked':''}>Keep search and suggestions</label></div><p id="apple-status" class="error" role="status" hidden></p>${tagPicker('import')}<div id="apple-results"></div>`;renderAppleResults();renderTagPicker('import')}
function renderAppleResults(){$('#apple-results').innerHTML=importRows.map(r=>`<div class="dev-result">${artwork(r)}<div class="result-info"><h3>${esc(r.title)}</h3><p>${esc(r.artist)} · ${esc(r.album)}</p><small>${[r.track_number?'Track '+r.track_number:Number(r.disc_count)>1?'Disc '+r.disc_number+' · source track '+r.source_track_number+' · position left blank':'',r.release_date,r.genres].filter(Boolean).map(esc).join(' · ')}</small></div>${imported.has(r.id)?'<span class="import-added">✓ Added</span>':`<button class="btn primary small" data-import="${r.id}">Add</button>`}</div>`).join('')}
async function runAppleSearch(){if(appleSearchBusy)return;importQuery=$('#apple-query').value;appleSearchBusy=true;const button=$('#apple-search button'),status=$('#apple-status');button.disabled=true;status.hidden=false;status.classList.remove('error');status.textContent='Searching Apple…';try{importRows=(await api('/api/dev/search_apple?q='+encodeURIComponent(importQuery))).map((r,i)=>({...r,id:i+1}));imported.clear();renderAppleResults();status.hidden=true;if(!importRows.length)$('#apple-results').innerHTML='<div class="empty">No results</div>'}catch(error){status.classList.add('error');status.textContent=error.message}finally{appleSearchBusy=false;if(button.isConnected)button.disabled=false}}

function tiles(items){return `<div class="workshop">${items.map(([title,icon])=>`<button class="tool-tile" data-tool="${title}"><span class="tool-icon">${icon}</span>${title}</button>`).join('')}</div>`}
function renderDevView(){if(devView==='overview')updateHealth();const node=$('#dev-main');$$('[data-dev]').forEach(b=>{b.classList.toggle('active',b.dataset.dev===devView);b.setAttribute('aria-pressed',String(b.dataset.dev===devView));if(b.dataset.dev===devView&&b.closest('details'))b.closest('details').open=true});if(devView==='metadata'){renderMetadata();return}if(devView==='explorer'){renderExplorer();return}if(['songs','artists','albums','tags'].includes(devView)){renderManage(devView);return}if(devView==='import'){renderImport();return}
 if(devView==='overall'){window.Overall.renderDev();return}
 if(devView==='bulk'){renderBulk();return}
 if(devView==='overview'){node.innerHTML=devTitle('Overview',`<button class="btn small" data-tool="Create backup">Create backup</button>`)+`<div class="stats">${stat('Songs',songs.length)}${stat('Artists',artists.length,'artist')}${stat('Albums',albums.filter(properAlbum).length,'album')}${stat('Tags',tags.length,'tag')}</div><div class="dev-overview-bottom">${tiles([['Apple Music','＋'],['Manual Elo correction','↗'],['Trivia maintenance','🎯'],['Database integrity','✓']])}<section class="panel"><h3>Database Health</h3><div class="health-row"><span>Integrity</span><strong class="song" id="health-integrity">Checking…</strong></div><div class="health-row"><span>Foreign-key errors</span><strong id="health-fk">Checking…</strong></div><div class="health-row"><span>Preview URLs</span><strong>${songs.filter(s=>s.audio_url).length} / ${songs.length}</strong></div></section></div>`;return}
 if(devView==='trivia'){node.innerHTML=devTitle('Trivia / Elo',`<button class="btn small danger" data-tool="Reset trivia history">Reset trivia</button>`)+tiles([['Trivia maintenance','🎯'],['Manual Elo correction','↗'],['Trivia records','🏆']]);return}
 if(devView==='database'){node.innerHTML=devTitle('Database')+tiles([['Database overview','▤'],['Database integrity','✓'],['Duplicate finder','⌕'],['Create backup','↧'],['Restore backup','↶'],['Reset match history','↻'],['Reset trivia history','↻'],['Reset tournament history','↻'],['Reset Elo Guesser history','↻'],['Reset Album Shelves history','↻'],['Reset competition','↻']]);return}
 if(['guesser_records','shelves_records','knowledge'].includes(devView)){window.SpecialModes.renderDevRecords(devView==='shelves_records'?'shelves':'guesser');return}
 if(devView==='export'){node.innerHTML=devTitle('Export & Sync')+tiles([['Export snapshot','↧'],['Sync database','↥']]);return}
 if(devView==='history'){node.innerHTML=devTitle('Match History',`<button class="btn small danger" data-tool="Reset match history">Reset matches / Elo</button>`)+`<section class="panel">${DB.history.map(matchRow).join('')}</section>`;return}
 if(devView==='tournaments'){node.innerHTML=devTitle('Tournaments',`<button class="btn small danger" data-tool="Reset tournament history">Reset tournaments</button>`)+`<div class="data-scroll"><table class="data-table"><thead><tr><th>ID</th><th>Size</th><th>Scope</th><th>Status</th><th>Champion</th><th>Runner-up</th><th>Third</th><th>Actions</th></tr></thead><tbody>${DB.tournaments.map(t=>`<tr><td>#${t.id}</td><td>${t.size}</td><td>${esc(t.scope_type)}</td><td>${esc(t.status)}</td><td>${clipped(byId(songs,t.champion_id)?.title||'—')}</td><td>${clipped(byId(songs,t.runner_up_id)?.title||'—')}</td><td>${clipped(byId(songs,t.third_place_id)?.title||'—')}</td><td>${t.status==='completed'?`<button class="btn small" data-edit-podium="${t.id}">Edit podium</button>`:''}<button class="btn small" data-bracket="${t.id}">View</button> <button class="btn small danger" data-delete-tournament="${t.id}">Delete</button></td></tr>`).join('')}</tbody></table></div>`;return}
 devView='explorer';renderExplorer();
}
let editTarget=null,toolTarget=null;
const dialog=$('#editor');
function openDialog(title,body,submit='Save'){stopAudio();$('#editor-title').textContent=title;$('#editor-fields').innerHTML=body+'<p id="editor-error" class="dialog-error" role="alert" tabindex="-1" hidden></p>';$('#editor-submit').textContent=submit;$('#editor-submit').disabled=false;dialog.showModal()}
function field(key,title,value,type='text',attrs=''){return `<div class="field"><label for="field-${key}">${title}</label><input id="field-${key}" name="${key}" type="${type}" value="${esc(value)}" ${attrs}></div>`}
function editRecord(type,id){const r=byId(records(type),id);if(!r)return;editTarget={type,id:r.id};toolTarget=null;let body='';if(type==='songs'){body=field('title','Title',r.title,'text','required')+field('artists','Artists',r.artist)+field('album','Album / release',r.album)+field('tags','Tags',r.tag_names)+tagPicker('edit')+field('audio_url','Preview URL',r.audio_url)+field('cover_url','Cover URL',r.cover_url)+field('track_number','Track number',r.track_number??'','number','min="1" step="1"');}if(type==='artists')body=field('name','Name',r.name,'text','required')+field('cover_url','Artwork URL',r.cover_url);if(type==='albums')body=field('title','Title',r.title,'text','required')+field('cover_url','Cover URL',r.cover_url)+field('release_date','Release date',r.release_date||'','date');if(type==='tags')body=field('name','Tag',r.name,'text','required')+`<div class="field tag-info-field"><label for="field-description">Tag info</label><textarea id="field-description" name="description" maxlength="2000" rows="5">${esc(r.description||'')}</textarea></div>`;openDialog('Edit '+label(type),'<div class="form-grid">'+body+'</div>');if(type==='songs')renderTagPicker('edit')}
function editorError(message){const node=$('#editor-error');if(node){node.textContent=message;node.hidden=false;node.focus()}else toast(message)}
async function saveEdit(values){const {type,id}=editTarget;const payload={...values,artist:values.artists,genres:values.tags};try{await api(`/api/dev/edit_${{songs:'song',artists:'artist',albums:'album',tags:'genre'}[type]}/${id}`,payload);await refreshData();editTarget=null;dialog.close();renderDevView();toast('Saved')}catch(error){editorError(error.message)}}
async function tool(name){editTarget=null;toolTarget={name};const routes={'Trivia':'/trivia','Tournament':'/tournament','Global stats':'/global_stats','Tournament archive':'/tournament_stats','Lock database':'/dev/logout'};if(routes[name]){location.href=routes[name];return}if(name==='Trivia records'){openDialog(name,field('high_score','Best player score',DB.global_stats?.trivia_high_score||0,'number','min="0" step="0.0001"')+field('high_streak','Best streak',DB.global_stats?.trivia_high_streak||0,'number','min="0" step="1"'));return}if(name==='Apple Music'){devView='import';renderDevView();return}
 if(['Manual Elo correction','Trivia maintenance'].includes(name)){if(!songs.length){toast('No songs');return}openDialog(name,maintenancePicker()+(name==='Manual Elo correction'?field('elo','New Elo','','number','required min="0" max="5000"'):triviaEditFields()+'<button class="btn small danger" type="button" data-clear-trivia disabled>Clear Stats</button>'));$('#editor-submit').disabled=true;renderMaintenanceMatches();$('#maintenance-query').focus();return}

 try{
 if(name==='Create backup'){const result=await api('/api/dev/backup',{});toast('Backup: '+result.backup);return}
 if(name==='Export snapshot'){const result=await api('/api/dev/export',{});toast(result.message);return}
 if(name==='Sync database'){openDialog(name,'<p>Push the database snapshot to the configured Git remote?</p>','Sync');return}
 if(name==='Restore backup'){const data=await api('/api/dev/overview');openDialog(name,`<div class="field"><label for="backup-select">Backup</label><select id="backup-select" name="filename">${data.backups.map(b=>`<option>${esc(b.name)}</option>`).join('')}</select></div>`,'Restore');return}
 if(historyResets[name]){const [scope,phrase]=historyResets[name],data=await api('/api/dev/reset-preview');const count=data.clear[({matches:'votes_and_history',trivia:'trivia_rounds',tournaments:'tournaments',guesser:'elo_guesses',shelves:'shelf_rounds'})[scope]];openDialog(name,`<div class="health-row"><span>${({matches:'Saved matches',trivia:'Saved trivia rounds',tournaments:'Saved tournaments',guesser:'Saved Elo guesses',shelves:'Saved shelf rounds'})[scope]}</span><strong>${count}</strong></div>`+field('confirmation','Type '+phrase,''),'Back up & reset');return}
 if(name==='Reset competition'){const data=await api('/api/dev/reset-preview');openDialog(name,`<div class="health-row"><span>Votes / trivia / tournaments</span><strong>${data.clear.votes_and_history} / ${data.clear.trivia_stats} / ${data.clear.tournaments}</strong></div>`+field('confirmation','Type RESET COMPETITION',''),'Back up & reset');return}
 if(name==='Database overview'){const data=await api('/api/dev/overview');openDialog(name,Object.entries(data.counts).map(([key,value])=>`<div class="health-row"><span>${esc(key)}</span><strong>${value}</strong></div>`).join(''),'Done');return}
 if(name==='Database integrity'){const data=await api('/api/dev/integrity');openDialog(name,`<div class="health-row"><span>SQLite</span><strong>${esc(data.integrity.join(', '))}</strong></div><div class="health-row"><span>Foreign-key errors</span><strong>${data.foreign_key_errors.length}</strong></div><div class="health-row"><span>Track-number conflicts</span><strong>${data.track_number_conflicts.length}</strong></div>${data.track_number_conflicts.map(s=>`<div class="health-row track-conflict"><div><strong>${esc(s.title)}</strong><small>${esc(s.album||'No album')} · track ${esc(s.track_number)} · ${esc(s.issue)}</small></div><button class="btn small" type="button" data-edit="songs" data-id="${s.id}">Edit</button></div>`).join('')}`,'Done');return}
 if(name==='Duplicate finder'){const groups=new Map();songs.forEach(s=>{const key=normal(s.title+' '+s.artist);groups.set(key,(groups.get(key)||[]).concat(s))});const duplicates=[...groups.values()].filter(g=>g.length>1);openDialog(name,duplicates.length?duplicates.map(g=>`<div class="health-row"><strong>${esc(g[0].title)}</strong><span>${g.map(s=>'#'+s.id).join(', ')}</span></div>`).join(''):'<div class="empty">No exact title / artist duplicates</div>','Done');return}
 }catch(error){toast(error.message)}
}
function deleteRecord(type,id){const r=byId(records(type),id);editTarget=null;toolTarget={name:'delete',type,id:Number(id)};openDialog('Delete '+label(type),`<strong>${esc(r.name)}</strong>`,'Delete')}
async function deleteLocal(type,id){try{await api(`/api/dev/delete_${{songs:'song',artists:'artist',albums:'album',tags:'genre'}[type]}/${id}`,null,'DELETE');await refreshData();renderDevView();dialog.close();toast('Deleted')}catch(error){toast(error.message)}}
// Real HTTP actions. All writes refresh the catalogue from the database.
async function api(url,data,method){const response=await fetch(url,{method:method||(data!==undefined?'POST':'GET'),headers:{'Content-Type':'application/json'},body:data!=null?JSON.stringify(data):undefined});let result;try{result=await response.json()}catch{throw new Error(response.redirected?'Sign in to the dev dashboard':'Request failed ('+response.status+')')}if(!response.ok)throw new Error(result.message||result.error||'Request failed');return result}
async function refreshData(){const fresh=await api('/api/collection');Object.assign(DB,fresh);rebuild()}
async function updateHealth(){try{const data=await api('/api/dev/overview');if($('#health-integrity'))$('#health-integrity').textContent=data.integrity;if($('#health-fk'))$('#health-fk').textContent=data.foreign_key_errors}catch(error){toast(error.message)}}
async function importSong(id){const row=byId(importRows,id);if(!row)return;const button=$(`[data-import="${id}"]`);button.disabled=true;try{await api('/api/dev/add_song',{...row,genres:[...new Set([...(row.genres||'').split(',').map(t=>t.trim()).filter(Boolean),...tags.filter(t=>importTags.has(t.id)).map(t=>t.name)])].join(', ')});imported.add(id);await refreshData();if(keepImport)renderAppleResults();else{importQuery='';importRows=[];$('#apple-query').value='';renderAppleResults()}toast('Added')}catch(error){toast(error.message);button.disabled=false}}
async function submitTool(values){const name=toolTarget?.name;let result;
 if(name==='delete'){await deleteLocal(toolTarget.type,toolTarget.id);return}
 if(name==='Edit podium'){result=await api('/api/dev/tournaments/'+toolTarget.id+'/placements',values)}
 else if(name==='Delete tournament'){result=await api('/api/dev/tournaments/'+toolTarget.id,null,'DELETE')}
 else if(name==='Manual Elo correction'){result=await api('/api/dev/elo-correction',{song_id:values.song_id,new_elo:values.elo})}
 else if(name==='Trivia records'){result=await api('/api/dev/trivia-records',values)}
 else if(name==='Trivia maintenance'){result=await api('/api/dev/trivia/'+values.song_id,Object.fromEntries(triviaEditNames.map(key=>[key,values[key]])))}
 else if(name==='Restore backup'){result=await api('/api/dev/restore-backup',{filename:values.filename})}
 else if(historyResets[name]){result=await api('/api/dev/reset-history/'+historyResets[name][0],{confirmation:values.confirmation})}
 else if(name==='Reset competition'){result=await api('/api/dev/reset-database',{confirmation:values.confirmation})}
 else if(name==='Sync database'){result=await api('/api/dev/sync',{})}
 else {dialog.close();return}
 await refreshData();dialog.close();if(page==='dev')renderDevView();toast(result.message||'Saved');
}
// V3.1 collection profiles share the song page's layout and player controls.
let profileState=null,albumPlayer=null;
const trackOrder=(a,b)=>(a.track_number||Infinity)-(b.track_number||Infinity)||a.id-b.id;
function compactArt(s,type='songs'){return `<span class="small-art ${type==='artists'?'circle':''}" aria-hidden="true">♫${s.cover_url?`<img src="${esc(s.cover_url)}" alt="" loading="lazy" onerror="this.hidden=true">`:''}</span>`}
function renderProfile(){
 const info=JSON.parse($('#profile-data').textContent),type=info.kind,item=records(type).find(r=>normal(r.name)===normal(info.name));if(!item)throw new Error('Profile unavailable');
 const tracks=linkedSongs(type,item),isAlbum=type==='albums',isTag=type==='tags',queueLabel=isAlbum?'album':isTag?'tag':'artist',kind=colour(type),ids=new Set(tracks.map(s=>s.id));
 profileState={type,item,tracks,sort:'rank'};
 const artistIds=[...new Set(tracks.flatMap(s=>s.artist_ids))],artistLinks=artistIds.map(id=>byId(artists,id)).filter(Boolean).map(a=>`<a class="artist" title="${esc(a.name)}" href="${urlFor('artists',a)}">${esc(a.name)}</a>`).join('<span class="separator muted">,</span>');
 const properAlbums=albums.filter(a=>properAlbum(a)&&a.song_ids.some(id=>ids.has(id))),rank=records(type).filter(r=>(!isAlbum||properAlbum(r))&&r.score>item.score).length+1;
 const queue=[...tracks].filter(s=>s.audio_url).sort(isAlbum?trackOrder:(a,b)=>b.elo_score-a.elo_score||a.title.localeCompare(b.title));
 const highlight=(track,title)=>track?`<article class="profile-highlight dashboard-surface" data-highlight="${title==='Track to rediscover'?'low':'high'}"><div>${compactArt(track)}</div><div><small>${title}</small><a class="song" href="${urlFor('songs',track)}" title="${esc(track.title)}">${esc(track.title)}</a><b class="standard">${Math.round(track.elo_score)} Elo</b></div></article>`:'';
 document.body.classList.add('profile-page');main.classList.remove('narrow');
 main.innerHTML=`<section class="panel song-profile profile-${kind} dashboard-surface"><div class="profile-media"><div class="album-cover-player"><button class="cover-button" data-audio="album-audio" data-album-play aria-label="Play ${queueLabel} previews" aria-pressed="false" ${queue.length?'':'disabled'}>${artwork(item,type)}<span class="play-overlay" aria-hidden="true">▶</span></button>${queue.length?`<button class="album-cover-step previous" data-album-step="-1" aria-label="Previous ${queueLabel} preview" title="Previous ${queueLabel} preview">‹</button><button class="album-cover-step next" data-album-step="1" aria-label="Next ${queueLabel} preview" title="Next ${queueLabel} preview">›</button>`:''}<div class="album-player-info" id="album-player-info" role="status">${window.ProfileUI.queueInfo(queue)}</div></div><audio id="album-audio" preload="none"></audio></div><div class="profile-copy"><h1 class="profile-page-title" title="${esc(item.name)}">${isTag?'# ':''}${esc(item.name)}</h1><div class="metadata">${isAlbum?artistLinks:`${tracks.length} tracks ${isTag?`<span class="separator muted">·</span> ${artistIds.length} artists `:''} <span class="separator muted">·</span> ${properAlbums.length} albums`}</div>${isTag?`<p class="tag-description">${esc(item.description||'')}</p>`:`<div class="tags profile-tag-list">${window.ProfileUI.tags(tracks,tags)}</div>`}<div class="profile-facts">${isAlbum&&item.release_date?`<span>Released <b>${esc(item.release_date.slice(0,10))}</b></span>`:''}<span>Highest track peak <b>${tracks.length?Math.round(Math.max(...tracks.map(s=>s.highest_elo||s.elo_score))):'—'} Elo</b></span></div></div></section>${window.ProfileUI.keyStats([['Impact',Math.round(item.impact_score),kind],['Global rank',isAlbum&&!properAlbum(item)?'—':'#'+rank,kind],['Average Elo',tracks.length?Math.round(item.avg_elo):'—','standard'],['Tracks',tracks.length,kind]])}<div class="profile-highlights">${highlight(tracks[0],'Highest-ranked track')}${tracks.length>1?highlight(tracks.at(-1),'Track to rediscover'):''}</div><div class="song-sections">${window.ProfileUI.stats(tracks,type)}${!isAlbum&&properAlbums.length?`<section class="panel profile-mode-panel dashboard-surface album" style="--section-color:var(--album)"><div class="section-head"><h2 class="album">Albums</h2></div><div class="profile-albums">${properAlbums.map(a=>`<article class="profile-album-card album">${artwork(a,'albums')}<a class="album" href="${urlFor('albums',a)}" title="${esc(a.title)}">${esc(a.title)}</a><small>${a.song_count} tracks · ${Math.round(a.score)} impact${a.release_date?' · '+esc(a.release_date.slice(0,4)):''}</small></article>`).join('')}</div></section>`:''}<section class="panel profile-mode-panel dashboard-surface ${kind}" style="--section-color:var(--${kind})"><div class="section-head"><h2 class="${kind}">${isAlbum?'Album Tracks':isTag?'Tagged Tracks':'Ranked Discography'}</h2>${isAlbum?'<div class="pill-nav" aria-label="Track order"><button class="pill active" data-profile-sort="rank" aria-pressed="true">Ranked</button><button class="pill" data-profile-sort="track" aria-pressed="false">Track order</button></div>':''}</div><div id="profile-tracks"></div></section></div>`;
 window.ProfileUI.fitTags();renderProfileTracks();attachPlayers();
 albumPlayer={label:queueLabel,queue,index:-1,advancing:false,failed:new Set(),finished:false,playRequested:false,primeTimer:null};bindAlbumAudio($('#album-audio'));
}
function renderProfileTracks(){const {type,tracks,sort}=profileState,rows=sort==='track'?[...tracks].sort(trackOrder):tracks;$('#profile-tracks').innerHTML=rows.map((s,i)=>`<div class="profile-track-row" data-profile-track="${s.id}"><span class="compact-rank">${sort==='track'?(s.track_number||'—'):i+1}</span>${compactArt(s)}<div class="compact-copy"><a class="song" title="${esc(s.title)}" href="${urlFor('songs',s)}">${esc(s.title)}</a><div class="metadata">${metadata(properAlbum(byId(albums,s.album_id))?s:{...s,album:''})}</div></div><div class="compact-score standard"><b>${Math.round(s.elo_score)}</b><small>Elo · ${s.matches_played} matches</small></div><button class="btn small" data-audio="track-audio-${s.id}" aria-label="Play ${esc(s.title)}" aria-pressed="false" ${s.audio_url?'':'disabled'}><span class="play-overlay">▶</span></button><audio id="track-audio-${s.id}" src="${esc(previewSource(s))}" preload="none"></audio></div>`).join('')||'<div class="empty">No linked tracks yet</div>';attachPlayers();markAlbumTrack()}
function markAlbumTrack(){if(!albumPlayer)return;const selected=albumPlayer.queue[albumPlayer.index];$$('[data-profile-track]').forEach(row=>row.classList.toggle('is-playing',!!selected&&Number(row.dataset.profileTrack)===selected.id&&!$('#album-audio').paused))}
function updateAlbumInfo(){const {queue,index}=albumPlayer;$('#album-player-info').innerHTML=window.ProfileUI.queueInfo(queue,index);markAlbumTrack()}
function bindAlbumAudio(audio){
 if(audio.dataset.albumBound)return;audio.dataset.albumBound='true';
 const current=()=>audio===$('#album-audio')&&albumPlayer?.playRequested;
 audio.addEventListener('timeupdate',()=>{if(current()&&!audio.paused&&audio.currentTime>=10&&!albumPlayer.advancing)advanceAlbum(1)});
 audio.addEventListener('ended',()=>{if(current()&&!albumPlayer.advancing)advanceAlbum(1)});
 audio.addEventListener('error',async()=>{if(!current()||albumPlayer.advancing)return;const state=albumPlayer,info=await window.PreviewPlayback?.problem(audio);if(state!==albumPlayer)return;if(info?.blocked){state.playRequested=false;window.PreviewPlayback?.stopAll();return}state.failed.add(state.index);startAlbumAt(state.index+1,true)});
 audio.addEventListener('play',()=>{if(audio===$('#album-audio'))$('[data-album-play]')?.setAttribute('aria-label','Pause '+albumPlayer.label+' previews')});
 audio.addEventListener('pause',()=>{if(audio===$('#album-audio'))$('[data-album-play]')?.setAttribute('aria-label','Play '+albumPlayer.label+' previews')});
}
async function startAlbumAt(index,play=true,direction=1){
 if(!albumPlayer)return;const state=albumPlayer;if(state.advancing){state.pending={index,play,direction};window.PreviewPlayback?.abandon($('#album-audio'));return}state.advancing=true;state.playRequested=play;clearTimeout(state.primeTimer);
 try{
  const count=state.queue.length;
  for(let offset=0;offset<count;offset++){
   const i=((index+offset*direction)%count+count)%count;if(state.failed.has(i))continue;
   let audio=$('#album-audio');state.loadingIndex=i;
   const old=audio;audio=window.PreviewPlayback?window.PreviewPlayback.replace(audio,previewSource(state.queue[i])):audio;if(!window.PreviewPlayback){audio.pause();audio.src=previewSource(state.queue[i]);audio.currentTime=0}
   audio.dataset.song=String(state.queue[i].id);if(audio!==old)delete audio.dataset.albumBound;bindAlbumAudio(audio);attachPlayers();
   if(!play){state.index=i;state.finished=false;updateAlbumInfo();return}
   try{await previewPlay(audio);if(state!==albumPlayer||!state.playRequested||!audio.isConnected){window.PreviewPlayback?.cancel(audio);return}state.index=i;state.finished=false;updateAlbumInfo();markAlbumTrack();
    state.primeTimer=setTimeout(()=>{if(state===albumPlayer&&state.playRequested&&!state.advancing)window.PreviewPlayback?.prime(previewSource(state.queue[(i+1)%count]))},650);return;
   }catch(error){if(error.name==='AbortError')return;if(error.name==='PreviewBlockedError'||error.name==='NotAllowedError'){state.playRequested=false;window.PreviewPlayback?.stopAll();if(error.name==='NotAllowedError')toast('Press the cover to play');return}state.failed.add(i)}
  }
  state.index=-1;state.finished=true;state.playRequested=false;window.PreviewPlayback?.stopAll();$('#album-audio')?.removeAttribute('src');$('#album-player-info').textContent='No playable previews';markAlbumTrack();
 }finally{state.advancing=false;state.loadingIndex=null;if(state.pending){const pending=state.pending;state.pending=null;await startAlbumAt(pending.index,pending.play,pending.direction)}}
}
async function advanceAlbum(step){if(!albumPlayer)return;const state=albumPlayer,current=state.pending?.index??state.loadingIndex??state.index;await startAlbumAt(current<0?(step<0?state.queue.length-1:0):current+step,state.playRequested,step<0?-1:1)}
async function toggleAlbum(){if(!albumPlayer)return;const state=albumPlayer,audio=$('#album-audio');if(state.playRequested){state.playRequested=false;state.pending=null;clearTimeout(state.primeTimer);if(window.PreviewPlayback)window.PreviewPlayback.cancel(audio);else audio.pause();markAlbumTrack();return}if(state.index<0){state.failed.clear();await startAlbumAt(0);return}if(!audio.getAttribute('src')||audio.dataset.song!==String(state.queue[state.index]?.id)){await startAlbumAt(state.index);return}state.playRequested=true;try{await previewPlay(audio);markAlbumTrack()}catch(error){if(error.name==='AbortError')return;if(error.name==='PreviewBlockedError'){state.playRequested=false;return}if(error.name==='NotAllowedError'){state.playRequested=false;toast('Press the cover to play')}else{state.failed.add(state.index);await startAlbumAt(state.index+1)}}}

