 if(b.dataset.albumStep)await advanceAlbum(Number(b.dataset.albumStep));
 if(b.dataset.rankingView){rankingView=b.dataset.rankingView;const params=new URLSearchParams(location.search);if(rankingView==='bottom')params.set('view','bottom');else params.delete('view');history.replaceState({},'',location.pathname+(params.size?'?'+params:''));if(page.startsWith('performance_'))renderPerformance(page.replace('performance_',''));else renderRanking(page.replace('rankings_',''))}
 if(b.dataset.performanceMetric){performanceMetric=b.dataset.performanceMetric;renderPerformance(page.replace('performance_',''))}
 if(b.dataset.profileSort){profileState.sort=b.dataset.profileSort;$$('[data-profile-sort]').forEach(n=>{n.classList.toggle('active',n.dataset.profileSort===profileState.sort);n.setAttribute('aria-pressed',String(n.dataset.profileSort===profileState.sort))});renderProfileTracks()}
