let bulkSelection=new Set(),bulkTags=new Set(),bulkAlbum=null,bulkQuery='',bulkAlbumFilter='',bulkArtistFilter='',bulkTagFilter='',bulkSelectedOnly=false;let importTags=new Set();
function bulkMatches(){const terms=normal(bulkQuery).split(/\s+/).filter(Boolean);return songs.filter(s=>terms.every(q=>normal([s.title,s.artist,s.album,s.tag_names,'#'+s.id].join(' ')).includes(q))&&(!bulkAlbumFilter||s.album_id===Number(bulkAlbumFilter))&&(!bulkArtistFilter||s.artist_ids.includes(Number(bulkArtistFilter)))&&(!bulkTagFilter||s.tag_ids.includes(Number(bulkTagFilter)))&&(!bulkSelectedOnly||bulkSelection.has(s.id)))}
function renderBulk(){$('#dev-main').innerHTML=devTitle('Bulk edits')+`<section class="panel"><div class="search-form"><input id="bulk-query" type="search" value="${esc(bulkQuery)}" placeholder="Find songs by title, artist, album or tag…" aria-label="Find songs for bulk editing"></div><div class="bulk-facets">${[['album',albums,bulkAlbumFilter],['artist',artists,bulkArtistFilter],['tag',tags,bulkTagFilter]].map(([key,rows,value])=>`<label>${key[0].toUpperCase()+key.slice(1)}<select id="bulk-filter-${key}"><option value="">All ${key}s</option>${[...rows].sort((a,b)=>a.name.localeCompare(b.name)).map(r=>`<option value="${r.id}" ${String(r.id)===value?'selected':''}>${esc(r.name)} (${r.song_count})</option>`).join('')}</select></label>`).join('')}<label class="checkbox-label"><input type="checkbox" id="bulk-selected-only" ${bulkSelectedOnly?'checked':''}>Selected only</label></div><div class="section-head"><div><button type="button" class="btn small" data-bulk-all>Select all matches</button> <button type="button" class="btn small" data-bulk-clear>Clear selection</button></div><strong id="bulk-count" class="song"></strong></div><div id="bulk-rows" class="bulk-selection"></div></section><section class="panel spaced-panel"><div class="field"><label for="bulk-action">Action</label><select id="bulk-action"><option value="move_album">Move to album</option><option value="add_tags">Add tags</option><option value="remove_tags">Remove tags</option></select></div><div id="bulk-actions" class="bulk-actions"></div><button class="btn primary" type="button" data-bulk-apply>Apply to selected songs</button><p id="bulk-error" class="error" hidden role="alert"></p></section>`;renderBulkRows();renderBulkActions()}
function renderBulkRows(){const rows=bulkMatches();$('#bulk-count').textContent=bulkSelection.size+' selected · '+rows.length+' matching';$('#bulk-rows').innerHTML=rows.map(s=>`<label class="bulk-row"><input type="checkbox" data-bulk-song="${s.id}" ${bulkSelection.has(s.id)?'checked':''}>${compactArt(s)}<span class="compact-copy"><strong>${esc(s.title)}</strong><small>${esc(s.artist)} · ${esc(s.album)} · Track ${s.track_number||'—'}</small><small class="tag">${esc(s.tag_names)}</small></span><small>#${s.id}</small></label>`).join('')||'<div class="empty">No matching songs</div>'}
function renderBulkActions(){const move=$('#bulk-action').value==='move_album';$('#bulk-actions').innerHTML=move?`<div class="search-form"><input id="bulk-album-query" type="search" placeholder="Find destination album…" aria-label="Destination album search"></div><strong id="bulk-album-selected" class="album">${esc(byId(albums,bulkAlbum)?.title||'')}</strong><div class="scope-results" id="bulk-albums"></div><label><input type="checkbox" id="bulk-clear-tracks">Clear selected track numbers</label>`:`<div class="search-form"><input id="bulk-tag-query" type="search" placeholder="Find tags…" aria-label="Find bulk tags"></div><div class="scope-results" id="bulk-tags"></div>`;move?renderBulkAlbums():renderBulkTags()}
function renderBulkAlbums(){const q=normal($('#bulk-album-query').value);$('#bulk-albums').innerHTML=albums.filter(a=>normal(a.title+' '+a.artist+' #'+a.id).includes(q)).slice(0,30).map(a=>`<button class="scope-option ${a.id===bulkAlbum?'selected':''}" data-bulk-album="${a.id}" type="button">${compactArt(a)}<strong class="album">${esc(a.title)}</strong><small>${a.song_count} songs · ${esc(a.artist)}<br>Tracks: ${esc(linkedSongs('albums',a).sort(trackOrder).map(t=>t.track_number||'—').join(', '))}</small></button>`).join('')||'<div class="empty">No albums. Create one in the Albums editor first.</div>'}
function renderBulkTags(){const q=normal($('#bulk-tag-query').value);$('#bulk-tags').innerHTML=tags.filter(t=>normal(t.name+' '+(t.description||'')).includes(q)).map(t=>`<label class="bulk-row"><input type="checkbox" data-bulk-tag="${t.id}" ${bulkTags.has(t.id)?'checked':''}><strong class="tag"># ${esc(t.name)}</strong><small>${esc(t.description||'')} · ${t.song_count} songs</small></label>`).join('')||'<div class="empty">No tags. Add a tag to a song in the editor first.</div>'}
async function applyBulk(){const button=$('[data-bulk-apply]'),err=$('#bulk-error');button.disabled=true;err.hidden=true;try{const result=await api('/api/dev/bulk_songs',{song_ids:[...bulkSelection],action:$('#bulk-action').value,album_id:bulkAlbum,tag_ids:[...bulkTags],clear_track_numbers:!!$('#bulk-clear-tracks')?.checked});await refreshData();renderBulkRows();toast(result.message)}catch(e){err.hidden=false;err.textContent=e.message}finally{button.disabled=false}}

function tagPicker(context){return `<details class="tag-picker ${context==='edit'?'tag-info-field':''}" ${context==='edit'?'open':''}><summary>${context==='import'?'Extra tags for new songs':'Choose existing tags'}</summary><input type="search" data-tag-query="${context}" placeholder="Find a tag by name or info…" aria-label="Find ${context} tags"><div class="tag-picker-list" id="tag-picks-${context}"></div></details>`}
function renderTagPicker(context){const root=$('#tag-picks-'+context);if(!root)return;const q=normal($(`[data-tag-query="${context}"]`).value),chosen=context==='import'?tags.filter(t=>importTags.has(t.id)).map(t=>normal(t.name)):($('#field-tags')?.value||'').split(',').map(normal);root.innerHTML=tags.filter(t=>normal(t.name+' '+(t.description||'')).includes(q)).sort((a,b)=>chosen.includes(normal(b.name))-chosen.includes(normal(a.name))||a.name.localeCompare(b.name)).map(t=>`<label class="tag-choice"><input type="checkbox" data-pick-tag="${t.id}" data-pick-context="${context}" ${chosen.includes(normal(t.name))?'checked':''}><span><b class="tag">${esc(t.name)}</b>${t.description?`<small>${esc(t.description)}</small>`:''}</span><small>${t.song_count}</small></label>`).join('')||'<div class="empty">No matching tags</div>'}
let metadataState={state:'idle'},metadataTimer=null,metadataBusy=false,metadataRequest=0;
function renderMetadata(){clearTimeout(metadataTimer);$('#dev-main').innerHTML=devTitle('Fill missing metadata')+`<section class="panel metadata-panel"><div class="section-head"><h3>Track numbers & release dates</h3></div><div class="metadata-actions"><label>Apple store<select id="metadata-country"><option value="gb">United Kingdom</option><option value="us">United States</option></select></label><button class="btn primary" type="button" data-metadata="scan">Scan missing values</button></div><p class="muted">Fill blanks only. Names, artwork and preview links stay unchanged.</p><div id="metadata-status" role="status" aria-live="polite"></div></section>`;refreshMetadata()}
function drawMetadata(){if(devView!=='metadata'||!$('#metadata-status'))return;const m=metadataState,running=['scanning','applying'].includes(m.state);$('[data-metadata="scan"]').disabled=running||metadataBusy;$('#metadata-country').disabled=running;$('#metadata-status').innerHTML=running?`<div class="health-row"><strong>${m.state==='scanning'?'Scanning':'Saving'} ${m.done} / ${m.total||'…'}</strong><button class="btn small" type="button" data-metadata="cancel" ${m.state==='applying'?'disabled':''}>Stop scan</button></div><p>${esc(m.album)}</p>`:m.state==='idle'?'':`<div class="mini-stats"><div><b>${m.tracks||0}</b><small>Track numbers</small></div><div><b>${m.date_changes?.length||0}</b><small>Release dates</small></div><div><b>${m.track_failures||0}</b><small>Track failures</small></div><div><b>${m.date_failures||0}</b><small>Date failures</small></div></div>${m.error||m.stopped?`<p class="error">${esc(m.error||m.stopped)}</p>`:''}<div class="metadata-actions">${m.state==='ready'?`<button class="btn primary" type="button" data-metadata="apply" ${m.tracks||m.dates?'':'disabled'}>Back up & fill matched blanks</button>`:''}${m.state==='applied'?'<strong class="song">✓ Matched blanks filled</strong>':''}<a class="btn" href="/api/dev/metadata/${encodeURIComponent(m.token)}/report">Download text report</a></div>${m.date_changes?.length?`<details class="metadata-review" open><summary>Release dates</summary>${m.date_changes.map(d=>`<div class="health-row"><span>${esc(d.title)}</span><strong>${esc(d.value)}</strong></div>`).join('')}</details>`:''}`}
async function refreshMetadata(){const seq=++metadataRequest;try{const result=await api('/api/dev/metadata');if(seq!==metadataRequest)return;metadataState=result;drawMetadata();if(['scanning','applying'].includes(metadataState.state)&&devView==='metadata')metadataTimer=setTimeout(refreshMetadata,1500)}catch(e){if($('#metadata-status'))$('#metadata-status').textContent=e.message}}
async function metadataAction(action){if(metadataBusy)return;metadataBusy=true;++metadataRequest;clearTimeout(metadataTimer);$$('[data-metadata]').forEach(b=>b.disabled=true);try{const path=action==='scan'?'/api/dev/metadata':`/api/dev/metadata/${encodeURIComponent(metadataState.token)}/${action}`;metadataState=await api(path,action==='scan'?{country:$('#metadata-country').value}:{});if(action==='apply'){await refreshData();toast('Metadata filled; backup saved')}drawMetadata();if(action!=='apply')metadataTimer=setTimeout(refreshMetadata,500)}catch(e){if($('#metadata-status')){const p=document.createElement('p');p.className='error';p.textContent=e.message;$('#metadata-status').append(p)}}finally{metadataBusy=false;if($('[data-metadata="scan"]'))$('[data-metadata="scan"]').disabled=['scanning','applying'].includes(metadataState.state);if($('[data-metadata="apply"]'))$('[data-metadata="apply"]').disabled=!(metadataState.tracks||metadataState.dates);if($('[data-metadata="cancel"]'))$('[data-metadata="cancel"]').disabled=metadataState.state==='applying'}}

